initializers.rivals = (function(...)
return function(UI, A, C, S, ENV, player, create, textButton, inputBox, connect, setText, trim, log)

-- ClientItem path and property names supplied in the user's reference document.
initializers.shaders(UI, A, playerGui, textButton, connect)


-- Runtime compatibility is checked on demand; navigation never loads a module.
do
    local enabled, loading, generation = false, false, 0
    local settings, fields, statusLabel, toggle = {}, {}
    local originals = setmetatable({}, {__mode = "k"})
    local bridge
    local definitions = {
        {id="Recoil", title="Recoil", keys={"ShootRecoil"}},
        {id="Speed", title="Projectile speed", keys={"ProjectileSpeed"}, positive=true},
        {id="Cooldown", title="Shot delay (seconds)", keys={"ShootCooldown", "QuickShotCooldown"}},
    }
    local function status(message, failed)
        if not S.closed and statusLabel then
            setText(statusLabel, message, failed and C.Error or C.Muted)
        end
    end
    local function refresh()
        if not S.closed and toggle then
            setText(toggle, loading and "CONNECTING... / CANCEL" or (enabled and "ON / TURN OFF" or "OFF / TURN ON"))
            toggle.BackgroundColor3 = enabled and C.Selection or C.Input
        end
    end
    local function restore()
        local failed = false
        for info, saved in pairs(originals) do
            for key, value in pairs(saved) do
                local ok = pcall(function()
                    -- Preserve a newer value written by the game or another tool.
                    if info[key] == value.applied then info[key] = value.original end
                end)
                if ok then saved[key] = nil else failed = true end
            end
            if next(saved) == nil then originals[info] = nil end
        end
        return not failed
    end
    local function stop()
        generation = generation + 1
        enabled, loading = false, false
        if bridge then bridge.handler = nil end
        local restored = restore()
        refresh()
        return restored
    end
    local function parse()
        local values, count = {}, 0
        for _, definition in ipairs(definitions) do
            local text = trim(fields[definition.id].Text)
            if text ~= "" then
                local value = tonumber(text)
                if not value or value ~= value or math.abs(value) == math.huge
                    or value < 0 or (definition.positive and value == 0) then
                    status(definition.title .. (definition.positive and ": enter a finite number above 0." or ": enter a finite number of 0 or above."), true)
                    return
                end
                for _, key in ipairs(definition.keys) do values[key] = value end
                count = count + 1
            end
        end
        return values, count
    end
    local function applyInfo(info)
        -- Validate all requested properties before changing any of them.
        for key in pairs(settings) do
            if type(info[key]) ~= "number" then return false end
        end
        local saved = originals[info] or {}
        originals[info] = saved
        for key, value in pairs(settings) do
            if not saved[key] then saved[key] = {original=info[key]} end
            saved[key].applied = value
            info[key] = value
        end
        return true
    end
    local function onInput(item)
        if not enabled or S.closed then return end
        local ok, changed = pcall(function()
            if type(item) ~= "table" or type(item.Info) ~= "table" then return false end
            return applyInfo(item.Info)
        end)
        if not ok then
            local restored = stop()
            status(restored and "OFF / This weapon's settings could not be changed." or "OFF / Could not restore every value. Rejoin to reset.", true)
        elseif changed then
            status("ON / Client settings applied. Server behavior may differ.")
        else
            status("ON / Waiting for a weapon with the selected properties.")
        end
    end
    local function apply()
        if S.closed then return end
        local values, count = parse()
        if not values then return end
        if not restore() then
            stop(); status("OFF / Could not restore every value. Rejoin to reset.", true); return
        end
        settings = values
        if count == 0 then
            stop(); status("OFF / Original values. Enter a value to customize.")
        else
            status(enabled and "ON / Saved. Applies on the next weapon input." or "Saved / Turn ON to apply on weapon input.")
        end
    end
    local function start()
        if S.closed then return end
        if enabled or loading then
            local restored = stop()
            status(restored and "OFF / Original values restored." or "OFF / Could not restore every value. Rejoin to reset.", not restored)
            return
        end
        local values, count = parse()
        if not values then return end
        if count == 0 then status("Enter at least one custom value. Blank keeps the original.", true); return end
        if game.GameId ~= 6035872082 and game.PlaceId ~= 17625359962 then
            status("Unavailable / Join RIVALS to use these controls.", true); return
        end
        local hook = ENV.hookfunction or hookfunction
        if type(hook) ~= "function" then status("Unavailable / hookfunction is not supported.", true); return end
        settings = values
        generation = generation + 1
        local request = generation
        loading = true; refresh(); status("Connecting to the weapon module...")
        task.spawn(function()
            if S.closed or generation ~= request then return end
            local ok, result = pcall(function()
                local node = player
                for _, name in ipairs({"PlayerScripts", "Modules", "ClientReplicatedClasses", "ClientFighter", "ClientItem"}) do
                    node = node:FindFirstChild(name)
                    assert(node, "Weapon module not found. Wait for RIVALS to load and retry.")
                end
                assert(node:IsA("ModuleScript"), "Unsupported weapon module.")
                local module = require(node)
                assert(type(module) == "table" and type(module.Input) == "function", "Unsupported weapon input function.")
                if S.closed or generation ~= request then return end
                local existing = ENV.__RagimRivalsBridge
                if type(existing) == "table" and existing.input == module.Input and type(existing.original) == "function" then
                    return existing
                end
                local record = {input=module.Input}
                local original
                original = hook(module.Input, function(...)
                    if record.handler then record.handler((...)) end
                    return original(...)
                end)
                assert(type(original) == "function", "Hook API did not return an original function.")
                record.original = original
                ENV.__RagimRivalsBridge = record
                return record
            end)
            if S.closed or generation ~= request then return end
            loading = false
            if not ok then
                refresh(); status("OFF / " .. tostring(result), true)
                log("RIVALS: " .. tostring(result)); return
            end
            bridge = result
            bridge.handler = onInput
            enabled = true; refresh()
            status("ON / Waiting for weapon input. Client changes only.")
        end)
    end
    function A.buildRivals(view)
        local function caption(name, text, order)
            return create("TextLabel", {Name=name, LayoutOrder=order,
                Size=UDim2.new(1,0,0,24), AutomaticSize=Enum.AutomaticSize.Y,
                BackgroundTransparency=1, Text=text, TextWrapped=true, Font=Enum.Font.Gotham,
                TextSize=12, TextColor3=C.Muted, TextXAlignment=Enum.TextXAlignment.Left}, view)
        end
        caption("RivalsIntro", "Blank = original. Recoil and delay allow 0; projectile speed must be above 0.\nShot delay sets both normal and quick-shot cooldowns. Values apply on weapon input.", 2)
        for index, definition in ipairs(definitions) do
            caption("RivalsLabel" .. definition.id, definition.title, index*2+1)
            local box = inputBox(view, UDim2.new(1,0,0,34), UDim2.new(), "Original")
            box.Name, box.LayoutOrder = "Rivals" .. definition.id, index*2+2
            fields[definition.id] = box
            connect(box.FocusLost, function(enter) if enter then apply() end end)
        end
        local actions = create("Frame", {Name="RivalsActions", LayoutOrder=9,
            Size=UDim2.new(1,0,0,36), BackgroundTransparency=1}, view)
        local function button(name, title, slot, callback)
            local button = textButton(actions, title, UDim2.new(1/3,-6,1,0), UDim2.new((slot-1)/3,0,0,0))
            button.Name, button.TextSize = name, 11
            button.TextWrapped = true
            connect(button.Activated, callback)
            return button
        end
        button("RivalsApply", "APPLY VALUES", 1, apply)
        toggle = button("RivalsToggle", "OFF / TURN ON", 2, start)
        button("RivalsReset", "RESET TO ORIGINAL", 3, function()
            local restored = stop()
            settings = {}
            for _, box in pairs(fields) do box.Text = "" end
            status(restored and "OFF / Original values restored." or "OFF / Could not restore every value. Rejoin to reset.", not restored)
        end)
        statusLabel = caption("RivalsStatus", "OFF / Set values, then turn ON in RIVALS. Compatibility is checked when enabled.", 12)
    end
    function A.cleanupRivals() stop() end
end

end
end)()
